/* App-läge: markera när dashboarden körs installerad (standalone) och fånga install-prompten. */
var _deferredInstall=null;
try{
  var _sa=(window.matchMedia&&window.matchMedia('(display-mode:standalone)').matches)||window.navigator.standalone===true;
  if(_sa)document.body.classList.add('standalone');
}catch(e){}
